/**
 * Main App Component
 * Application entry point with routing and providers
 */

import React, { useState } from "react";
import { BrowserRouter as Router, Routes, Route, Navigate, useNavigate } from "react-router-dom";
import { AuthProvider, useAuth } from "./hooks/useAuth";
import { TenantProvider } from "./hooks/useTenant";

// Pages
import {
  TenantDashboard,
  BillingDashboard,
  ObservabilityDashboard,
  AppManagementConsole,
  RBACManagement,
  PlatformAdminConsole,
  SettingsPage,
  HelpPage,
  AppDetailPage,
  OrchestratorPage,
  AboutPage,
  HowItWorksPage,
  PricingPage,
  PrivacyPolicyPage,
  TermsOfServicePage,
} from "./pages";

// Style
import "./styles/globals.css";

// Login Page
const LoginPage: React.FC = () => {
  const navigate = useNavigate()
  const [email, setEmail] = useState('')
  const [password, setPassword] = useState('')
  const [error, setError] = useState('')

  const { login } = useAuth()

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!email || !password) {
      setError('Please enter your email and password.')
      return
    }
    try {
      await login(email, password)
      navigate('/dashboard')
    } catch {
      setError('Login failed. Please try again.')
    }
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-blue-900 via-blue-800 to-indigo-900 flex flex-col">
      {/* Top bar */}
      <header className="relative z-10 px-6 py-4 flex items-center justify-between">
        <div className="flex items-center gap-2">
          <div className="w-7 h-7 rounded-lg bg-white/20 flex items-center justify-center text-white font-bold text-xs">
            S
          </div>
          <span className="text-sm font-semibold text-white">SRP Autonomous OS</span>
        </div>
        <div className="flex items-center gap-3">
          <a href="/about" className="text-xs text-blue-200 hover:text-white transition-colors">About</a>
          <a href="/pricing" className="text-xs text-blue-200 hover:text-white transition-colors">Pricing</a>
        </div>
      </header>

      {/* Main */}
      <div className="relative z-10 flex flex-1 items-center justify-center px-4 py-12">
        <div className="w-full mx-auto" style={{ maxWidth: '400px' }}>
          {/* Badge */}
          <div className="flex justify-center mb-6">
            <span className="inline-flex items-center gap-1.5 px-3 py-1 rounded-full border border-white/30 text-white text-[11px] font-medium bg-white/10 backdrop-blur-sm">
              <span className="w-1.5 h-1.5 rounded-full bg-blue-300 animate-pulse" />
              AI-Powered Business OS
            </span>
          </div>

          <h1 className="text-center text-2xl font-bold text-white mb-1">
            Welcome back
          </h1>
          <p className="text-center text-sm text-blue-200 mb-7">
            Sign in to access your business applications
          </p>

          {/* Card */}
          <div className="bg-white rounded-xl shadow-2xl p-8">
            {error && (
              <div className="mb-4 px-3 py-2 bg-red-50 border border-red-200 rounded-lg text-red-600 text-xs">
                {error}
              </div>
            )}
            <form onSubmit={handleSubmit} className="space-y-4">
              <div>
                <label className="block text-sm text-gray-700 font-medium mb-1.5">Email address</label>
                <input
                  type="email"
                  placeholder="you@company.com"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  className="w-full px-4 py-2.5 bg-white border border-gray-300 focus:border-blue-500 focus:ring-2 focus:ring-blue-100 focus:outline-none rounded-lg text-sm text-gray-900 placeholder-gray-400 transition-colors"
                  required
                />
              </div>
              <div>
                <label className="block text-sm text-gray-700 font-medium mb-1.5">Password</label>
                <input
                  type="password"
                  placeholder="••••••••"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  className="w-full px-4 py-2.5 bg-white border border-gray-300 focus:border-blue-500 focus:ring-2 focus:ring-blue-100 focus:outline-none rounded-lg text-sm text-gray-900 placeholder-gray-400 transition-colors"
                  required
                />
              </div>
              <button
                type="submit"
                className="w-full mt-1 py-2.5 rounded-lg bg-blue-600 hover:bg-blue-700 text-white text-sm font-semibold transition-colors shadow-md"
              >
                Sign In →
              </button>
            </form>
          </div>

          <p className="mt-4 text-center text-[11px] text-blue-300">
            Demo mode — any email and password
          </p>
        </div>
      </div>

      {/* Footer note */}
      <footer className="relative z-10 px-6 py-4 border-t border-white/10 text-center">
        <p className="text-[11px] text-blue-300">
          © {new Date().getFullYear()} SRP Autonomous OS. All rights reserved. ·{" "}
          <a href="/privacy-policy" className="hover:text-white transition-colors">Privacy</a>
          {" · "}
          <a href="/terms-of-service" className="hover:text-white transition-colors">Terms</a>
        </p>
      </footer>
    </div>
  )
}

// Protected Route wrapper
const ProtectedRoute: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const token = localStorage.getItem("srp_auth_token");

  if (!token) {
    return <Navigate to="/login" replace />;
  }

  return <>{children}</>;
};

export const App: React.FC = () => {
  return (
    <Router future={{ v7_startTransition: true, v7_relativeSplatPath: true }}>
      <AuthProvider>
        <TenantProvider>
          <Routes>
            {/* Public Routes */}
            <Route path="/login" element={<LoginPage />} />

            {/* Protected Routes */}
            <Route
              path="/dashboard"
              element={
                <ProtectedRoute>
                  <TenantDashboard />
                </ProtectedRoute>
              }
            />
            <Route
              path="/billing"
              element={
                <ProtectedRoute>
                  <BillingDashboard />
                </ProtectedRoute>
              }
            />
            <Route
              path="/metrics"
              element={
                <ProtectedRoute>
                  <ObservabilityDashboard />
                </ProtectedRoute>
              }
            />
            <Route
              path="/apps"
              element={
                <ProtectedRoute>
                  <AppManagementConsole />
                </ProtectedRoute>
              }
            />
            <Route
              path="/apps/:appId"
              element={
                <ProtectedRoute>
                  <AppDetailPage />
                </ProtectedRoute>
              }
            />
            <Route
              path="/orchestrator"
              element={
                <ProtectedRoute>
                  <OrchestratorPage />
                </ProtectedRoute>
              }
            />
            <Route
              path="/users"
              element={
                <ProtectedRoute>
                  <RBACManagement />
                </ProtectedRoute>
              }
            />
            <Route
              path="/admin"
              element={
                <ProtectedRoute>
                  <PlatformAdminConsole />
                </ProtectedRoute>
              }
            />

            {/* Public informational routes */}
            <Route path="/about" element={<AboutPage />} />
            <Route path="/how-it-works" element={<HowItWorksPage />} />
            <Route path="/pricing" element={<PricingPage />} />
            <Route path="/privacy-policy" element={<PrivacyPolicyPage />} />
            <Route path="/terms-of-service" element={<TermsOfServicePage />} />

            {/* Default redirect */}
            <Route path="/" element={<Navigate to="/dashboard" replace />} />
            <Route
              path="/settings"
              element={
                <ProtectedRoute>
                  <SettingsPage />
                </ProtectedRoute>
              }
            />
            <Route
              path="/help"
              element={
                <ProtectedRoute>
                  <HelpPage />
                </ProtectedRoute>
              }
            />
          </Routes>
        </TenantProvider>
      </AuthProvider>
    </Router>
  );
};

export default App;
